#include <vector>
#include <algorithm>

class Solution {
public:
    int rangeSum(std::vector<int>& nums, int n, int left, int right) {
        const int MOD = 1e9 + 7;
        std::vector<int> sums;
        sums.reserve(n * (n + 1) / 2);
        for (int i = 0; i < n; ++i) {
            int cur = 0;
            for (int j = i; j < n; ++j) {
                cur += nums[j];
                sums.push_back(cur);
            }
        }
        std::sort(sums.begin(), sums.end());
        long long ans = 0;
        for (int i = left - 1; i < right; ++i) {
            ans = (ans + sums[i]) % MOD;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int rangeSum(int[] nums, int n, int left, int right) {
        final int MOD = 1000000007;
        int total = n * (n + 1) / 2;
        int[] sums = new int[total];
        int idx = 0;
        for (int i = 0; i < n; i++) {
            int cur = 0;
            for (int j = i; j < n; j++) {
                cur += nums[j];
                sums[idx++] = cur;
            }
        }
        Arrays.sort(sums);
        long ans = 0;
        for (int i = left - 1; i < right; i++) {
            ans = (ans + sums[i]) % MOD;
        }
        return (int) ans;
    }
}

var rangeSum = function(nums, n, left, right) {
    const MOD = 1000000007n;
    const sums = [];
    for (let i = 0; i < n; i++) {
        let cur = 0;
        for (let j = i; j < n; j++) {
            cur += nums[j];
            sums.push(cur);
        }
    }
    sums.sort((a, b) => a - b);
    let ans = 0n;
    for (let i = left - 1; i < right; i++) {
        ans = (ans + BigInt(sums[i])) % MOD;
    }
    return Number(ans);
};
